import React, { useState, useEffect, useLayoutEffect, useRef } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Expertise from './components/Expertise';
import Games from './components/Games';
import About from './components/About';
import Contact from './components/Contact';
import HoldingPortal from './components/HoldingPortal';

// Define available pages
export type Page = 'home' | 'games' | 'expertise' | 'studio' | 'contact';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('home');
  const scrollRef = useRef<HTMLDivElement>(null);

  // FAILSAFE SUPREMO: Resetar a restauração de scroll do navegador ao montar
  useEffect(() => {
    if ('scrollRestoration' in history) {
      history.scrollRestoration = 'manual';
    }
  }, []);

  // ESTRATÉGIA 3 CAMADAS PARA SCROLL TOP
  useLayoutEffect(() => {
    // 1. Imediato (Síncrono)
    window.scrollTo(0, 0);
    document.body.scrollTop = 0;
    document.documentElement.scrollTop = 0;

    // 2. Loop de Força (Garante que layout shifts não empurrem a tela para baixo)
    let frameId: number;
    let count = 0;

    const forceScroll = () => {
      if (count < 5) { // Tenta por 5 frames seguidos
        window.scrollTo(0, 0);
        document.body.scrollTop = 0;
        document.documentElement.scrollTop = 0;
        count++;
        frameId = requestAnimationFrame(forceScroll);
      }
    };

    frameId = requestAnimationFrame(forceScroll);

    return () => cancelAnimationFrame(frameId);
  }, [currentPage]);

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return <Hero setPage={setCurrentPage} />;
      case 'games':
        return <Games />;
      case 'expertise':
        return <Expertise setPage={setCurrentPage} />;
      case 'studio':
        return <About />;
      case 'contact':
        return <Contact />;
      default:
        return <Hero setPage={setCurrentPage} />;
    }
  };

  return (
    <div ref={scrollRef} className="w-full max-w-[100vw] min-h-screen bg-black text-white selection:bg-white selection:text-black font-sans flex flex-col overflow-x-hidden">
      <Navbar currentPage={currentPage} setPage={setCurrentPage} />

      {/* 
         KEY PROP CRUCIAL: 
         Ao adicionar key={currentPage}, forçamos o React a destruir o DOM antigo e criar um novo.
         Isso elimina fisicamente a altura da página anterior antes da nova renderizar.
      */}
      <main className="flex-grow relative z-10 w-full min-h-[100vh]" key={currentPage}>
        {renderPage()}
      </main>

      <footer className="py-8 bg-black border-t border-white/10 text-center relative z-10 mt-auto w-full">
        <div className="max-w-7xl mx-auto px-4 flex flex-col items-center">
          <h2 className="font-display font-black text-2xl text-white mb-2 uppercase tracking-tighter">STYH</h2>
          <p className="text-gray-600 text-[10px] font-mono mb-2 uppercase tracking-widest">
            © {new Date().getFullYear()} STYH GAMES • Ferraz de Vasconcelos - SP
          </p>
          <div className="flex flex-wrap justify-center gap-4 text-[10px] text-gray-700 font-mono uppercase px-4">
            <span>Paulo Gabriel L.S.</span> • <span>Daniel Pinhal Filho</span> • <span>Douglas Ambrósio</span>
          </div>
        </div>
      </footer>

      <HoldingPortal />
    </div>
  );
};

