import React, { useState, useEffect, useLayoutEffect, useRef } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Expertise from './components/Expertise';
import Games from './components/Games';
import About from './components/About';
import Contact from './components/Contact';
import HoldingPortal from './components/HoldingPortal';

// Define available pages
export type Page = 'home' | 'games' | 'expertise' | 'studio' | 'contact';

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('home');
  const scrollRef = useRef<HTMLDivElement>(null);

  // FAILSAFE SUPREMO: Desabilita a memória de scroll do navegador
  useEffect(() => {
    if ('scrollRestoration' in history) {
      history.scrollRestoration = 'manual';
    }
  }, []);

  // --- O CORAÇÃO DA SOLUÇÃO ---
  // Esta função substitui o setCurrentPage direto.
  // Ela executa a "Camada 1" (Scroll Imediato) antes de qualquer renderização.
  const handlePageTransition = (newPage: Page) => {
    // 1. FORÇA BRUTA IMEDIATA
    // Rola para o topo antes do React sequer saber que a página mudou.
    window.scrollTo(0, 0);
    document.body.scrollTop = 0;
    document.documentElement.scrollTop = 0;

    // Atualiza o estado
    setCurrentPage(newPage);
  };

  // CAMADA 2: Sincronização de Layout
  // Executa milissegundos após o DOM ser criado, mas antes de aparecer na tela.
  useLayoutEffect(() => {
    window.scrollTo(0, 0);
    document.body.scrollTop = 0;
    document.documentElement.scrollTop = 0;
  }, [currentPage]);

  // CAMADA 3: Varredura de Segurança
  // Caso o navegador tente restaurar a posição antiga ou imagens carreguem empurrando o conteúdo.
  useEffect(() => {
    // Executa no próximo ciclo de evento
    const t1 = setTimeout(() => window.scrollTo(0, 0), 10);
    // Executa após um frame curto
    const t2 = setTimeout(() => window.scrollTo(0, 0), 40);
    // Executa como garantia final
    const t3 = setTimeout(() => window.scrollTo(0, 0), 100);

    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
      clearTimeout(t3);
    };
  }, [currentPage]);

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        // Passamos a nossa função "turbinada" em vez do setPage puro
        return <Hero setPage={handlePageTransition} />;
      case 'games':
        return <Games />;
      case 'expertise':
        return <Expertise setPage={handlePageTransition} />;
      case 'studio':
        return <About />;
      case 'contact':
        return <Contact />;
      default:
        return <Hero setPage={handlePageTransition} />;
    }
  };

  return (
    <div ref={scrollRef} className="w-full max-w-[100vw] min-h-screen bg-black text-white selection:bg-white selection:text-black font-sans flex flex-col overflow-x-hidden">
      <Navbar currentPage={currentPage} setPage={handlePageTransition} />

      {/* 
         KEY PROP CRUCIAL:
         key={currentPage} obriga o React a DESTRUIR o <main> antigo e criar um novo.
         Isso zera a altura do container fisicamente.
      */}
      <main className="flex-grow relative z-10 w-full min-h-[100vh]" key={currentPage}>
        {renderPage()}
      </main>

      <footer className="py-8 bg-black border-t border-white/10 text-center relative z-10 mt-auto w-full">
        <div className="max-w-7xl mx-auto px-4 flex flex-col items-center">
          <h2 className="font-display font-black text-2xl text-white mb-2 uppercase tracking-tighter">STYH</h2>
          <p className="text-gray-600 text-[10px] font-mono mb-2 uppercase tracking-widest">
            © {new Date().getFullYear()} STYH GAMES • Ferraz de Vasconcelos - SP
          </p>
          <div className="flex flex-wrap justify-center gap-4 text-[10px] text-gray-700 font-mono uppercase px-4">
            <span>Paulo Gabriel L.S.</span> • <span>Daniel Pinhal Filho</span> • <span>Douglas Ambrósio</span>
          </div>
        </div>
      </footer>

      <HoldingPortal />
    </div>
  );
};

export default App;

